"""Shared parsing helpers for the governance tools.

Standard library only. Every tool in this directory imports this module, so
it is copied alongside them into a generated project's governance/checks/.
"""

import datetime
import os
import re
import subprocess
import sys
import unicodedata

SURFACES_REL = "governance/SURFACES.md"
LEDGER_REL = "docs/LEDGER.md"

RISK_PATHS_REL = "governance/risk-paths.toml"
AGENTS_MD_REL = "AGENTS.md"
# model S-009 AC1: this file's presence switches on the v3 checks; its content is never read.
V3_SWITCH_REL = "governance/v3.toml"

ORCHESTRATOR = "orchestrator"
OWNER = "owner"                       # reserved reviewer id: the human owner
AGENT_DOMAIN = "agents.invalid"       # agent commit emails are <id>@agents.invalid
CLASSES = ("builder", "reviewer", "reader", "researcher")
REVIEWER_CLASSES = ("reviewer", "reader", "researcher")
TIERS = ("T0", "T1", "T2", "T3")
RISK_CLASSES = ("R0", "R1", "R2", "R3")
STATUSES = ("installed", "planned")
AUTHORITIES = ("autonomous", "proposes", "escalates")

LEDGER_TYPES = (
    "ruling", "predeclaration", "reading", "kill", "incident", "postmortem",
    "delegation", "defaulted", "tier-change", "rule-experiment", "correction",
)

ENTRY_HEADING_RE = re.compile(r"^## (L-\d{4,}[a-z]?)\b(.*)$")
FIELD_RE = re.compile(r"^([a-z_]+):(.*)$")
LEDGER_ID_RE = re.compile(r"^L-\d{4,}[a-z]?$")
DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def is_v3(root):
    """True when the project at root declares v3: governance/v3.toml exists (model S-009 AC1)."""
    return os.path.isfile(os.path.join(root, V3_SWITCH_REL))


class UsageError(Exception):
    """A usage or parse problem: the tool exits 2."""


class GitError(UsageError):
    """A git command failed."""


# --------------------------------------------------------------------------
# Files and git


def decode_utf8(data, where):
        raise UsageError("%s %r is not a commit in %s" % (what, ref, root))
    return git(root, ["rev-parse", "--verify", "-q", "%s^{commit}" % ref]).decode().strip()


def normalize_path(path):
    path = path.strip().replace("\\", "/")
    while path.startswith("./"):
        path = path[2:]
    return path


def resolve_under_root(root, path, what="path"):
    """Return `path` as a POSIX path relative to `root`.

    `path` may be relative to root or absolute. Raises UsageError when it
    points outside root (including via `..` or a symlink) or at root itself.
    """
    if not path:
        raise UsageError("%s is empty" % what)
    root_real = os.path.realpath(root)
    full = path if os.path.isabs(path) else os.path.join(root_real, path)
    full_real = os.path.realpath(full)
    rel = os.path.relpath(full_real, root_real)
    if rel == "." or rel == ".." or rel.startswith(".." + os.sep) or os.path.isabs(rel):
        raise UsageError("%s %r is outside --root %s" % (what, path, root))
    return rel.replace(os.sep, "/")


def read_file_list(path):
    """Read a file list: one path per line, empty lines ignored.

    Only the line ending (newline, and a CR before it) is removed; every other
    character, including leading or trailing spaces, is part of the path.
    """
    try:
        with open(path, "rb") as fh:
            data = fh.read()
    except OSError as exc:
        raise UsageError("cannot read file list %s: %s" % (path, exc))
    text = decode_utf8(data, "file list %s" % path)
    out = []
    for line in text.split("\n"):
        if line.endswith("\r"):
            line = line[:-1]
        if line:
            out.append(line)
    return out


def git(root, args, input=None):
    """Run git in root and return stdout as bytes, or raise GitError."""
    try:
        proc = subprocess.run(
            ["git"] + list(args), cwd=root, input=input,
            stdout=subprocess.PIPE, stderr=subprocess.PIPE,
        )
    except OSError as exc:
        raise GitError("cannot run git: %s" % exc)
    if proc.returncode != 0:
        msg = proc.stderr.decode("utf-8", "replace").strip()
        raise GitError("git %s failed in %s: %s" % (" ".join(args), root, msg))
    return proc.stdout


def git_ok(root, args):
    """Run git in root; return True when it exits 0."""
    try:
        proc = subprocess.run(
            ["git"] + list(args), cwd=root,
            stdout=subprocess.PIPE, stderr=subprocess.PIPE,
        )
    except OSError:
        return False
    return proc.returncode == 0


def split_z(data):
    """Split NUL-separated git output. Paths are returned exactly as git gives them."""
    return [p for p in data.decode("utf-8", "surrogateescape").split("\0") if p]


# --------------------------------------------------------------------------
# Globs


def _segment_regex(seg):
    out = []
    for ch in seg:
        if ch == "*":
            out.append("[^/]*")
        elif ch == "?":
            out.append("[^/]")
        else:
            out.append(re.escape(ch))
    return "".join(out)


def glob_to_regex(pattern):
    """Translate a surface glob into an anchored regular expression.

    `**/` matches zero or more leading directory segments; a trailing
    `dir/**` matches `dir` itself and everything below it; `*` and `?`
    never cross `/`; everything else is literal.
    """
    pattern = normalize_path(pattern).lstrip("/")
    parts = []
    for seg in pattern.split("/"):
        # Consecutive `**` segments mean the same as one.
        if seg == "**" and parts and parts[-1] == "**":
            continue
        parts.append(seg)
    n = len(parts)
    out = []
    for i, seg in enumerate(parts):
        last = i == n - 1
        if seg == "**":
            if last:
                out.append(".*" if i == 0 else "(?:/.*)?")
            else:
                out.append("(?:[^/]+/)*")
        else:
            out.append(_segment_regex(seg))
            next_is_trailing_star = (i + 1 == n - 1 and parts[i + 1] == "**")
            if not last and not next_is_trailing_star:
                out.append("/")
    return re.compile("^" + "".join(out) + "$")


_GLOB_CACHE = {}


def glob_match(pattern, path):
    rx = _GLOB_CACHE.get(pattern)
    if rx is None:
        rx = glob_to_regex(pattern)
        _GLOB_CACHE[pattern] = rx
    return rx.match(path) is not None


def surface_includes(rules, path):
    """rules: list of (negated, glob). Later matching lines win."""
    included = False
    for negated, pattern in rules:
        if glob_match(pattern, path):
            included = not negated
    return included


# --------------------------------------------------------------------------
# Fenced blocks


_FENCE_RE = re.compile(r"^ {0,3}(`{3,}|~{3,})(.*)$")


def fenced_blocks(text):
# SURFACES.md


class RosterRow(object):
    def __init__(self, agent_id, cls, status, authority, defaulted, lineno):
        self.id = agent_id
        self.cls = cls
        self.status = status
        self.authority = authority
        self.defaulted = defaulted
        self.lineno = lineno


class Surfaces(object):
    def __init__(self):
        self.roster = []          # RosterRow, file order
        self.blocks = {}          # id -> list of (negated, glob)
        self.block_lines = {}     # id -> line number of the fence
        self.problems = []        # (lineno, message) found while parsing
        self.humans = []          # (lineno, name, email) from the `humans` block
        self.exempt = []          # (lineno, sha, ledger id) from the `exempt` block
        self.humans_line = None   # line of the first `humans` fence
        self.exempt_line = None   # line of the first `exempt` fence

    def roster_ids(self):
        return [r.id for r in self.roster]

    def row(self, agent_id):
        for r in self.roster:
            if r.id == agent_id:
                return r
        return None

    def reviewer_ids(self):
        """Reviewer-class ids: classes reviewer, reader and researcher."""
        return [r.id for r in self.roster if r.cls in REVIEWER_CLASSES]

    def builder_ids(self):
        return [r.id for r in self.roster if r.cls == "builder"]

    def is_reviewer_class(self, agent_id):
        row = self.row(agent_id)
        return row is not None and row.cls in REVIEWER_CLASSES

    def human_emails(self):
        """Lower-cased emails of the humans block."""
        return set(email.lower() for _, _, email in self.humans)

    def exempt_map(self):
        """Lower-cased full sha -> ledger id (first line wins)."""
        out = {}
        for _, sha, lid in self.exempt:
            out.setdefault(sha.lower(), lid)
        return out

    def owners(self, path):
        return sorted(a for a, rules in self.blocks.items()
                      if surface_includes(rules, path))


def parse_surfaces(text):
    s = Surfaces()
    for info, body, open_no in fenced_blocks(text):
        if info == "roster":
            for lineno, line in body:
                content = strip_comment(line)
                if not content:
                    continue
                fields = content.split()
                if len(fields) not in (3, 4):
                    s.problems.append((lineno, "roster line must be 'id class status [authority]', got %r" % content))
                    continue
                defaulted = len(fields) == 3
                authority = "autonomous" if defaulted else fields[3]
                s.roster.append(RosterRow(fields[0], fields[1], fields[2],
                                          authority, defaulted, lineno))
        elif info.startswith("surface:"):
            agent_id = info[len("surface:"):].strip()
            if not agent_id:
                s.problems.append((open_no, "surface block has no agent id"))
                continue
            if agent_id in s.blocks:
                s.problems.append((open_no, "second surface:%s block (first at line %d); each agent gets one block"
                                   % (agent_id, s.block_lines[agent_id])))
                continue
            rules = []
            for lineno, line in body:
                content = strip_comment(line)
                if not content:
                    continue
                negated = content.startswith("!")
                pattern = content[1:].strip() if negated else content
                if not pattern:
                    s.problems.append((lineno, "empty exclusion in surface:%s" % agent_id))
                    continue
                rules.append((negated, pattern))
            s.blocks[agent_id] = rules
            s.block_lines[agent_id] = open_no
        elif info == "humans":
            if s.humans_line is not None:
                s.problems.append((open_no, "second humans block (first at line %d); list every human in one block"
                                   % s.humans_line))
                continue
            s.humans_line = open_no
            _parse_humans(s, body)
        elif info == "exempt":
            if s.exempt_line is not None:
                s.problems.append((open_no, "second exempt block (first at line %d); list every exemption in one block"
                                   % s.exempt_line))
                continue
            s.exempt_line = open_no
            _parse_exempt(s, body)
    return s


HUMAN_RE = re.compile(r"^(.+?)\s*<([^<>\s]+@[^<>\s]+)>$")
SHA_RE = re.compile(r"^[0-9a-fA-F]{40}$")


def _parse_humans(s, body):
    seen = {}
    for lineno, line in body:
        content = strip_comment(line)
        if not content:
            continue
        m = HUMAN_RE.match(content)
        if not m:
            s.problems.append((lineno, "humans line must be 'Name <email>', got %r" % content))
            continue
        name, email = m.group(1).strip(), m.group(2)
        low = email.lower()
        if low.endswith("@" + AGENT_DOMAIN):
            s.problems.append((lineno, "humans email %s ends in @%s — that domain is reserved for agents"
                               % (email, AGENT_DOMAIN)))
            continue
        if low in seen:
            s.problems.append((lineno, "duplicate humans email %s (first at line %d)" % (email, seen[low])))
            continue
        seen[low] = lineno
        s.humans.append((lineno, name, email))


def _parse_exempt(s, body):
    seen = {}
    for lineno, line in body:
        content = strip_comment(line)
        if not content:
            continue
        fields = content.split()
        if len(fields) != 2:
            s.problems.append((lineno, "exempt line must be '<40-hex commit sha> <ledger id>', got %r" % content))
            continue
        sha, lid = fields
        if not SHA_RE.match(sha):
            s.problems.append((lineno, "exempt sha %r is not a full 40-hex commit sha" % sha))
            continue
        low = sha.lower()
        if low in seen:
            s.problems.append((lineno, "duplicate exempt sha %s (first at line %d)" % (sha, seen[low])))
            continue
        seen[low] = lineno
        s.exempt.append((lineno, sha, lid))


def load_surfaces(root):
    path = os.path.join(root, SURFACES_REL)
    if not os.path.isfile(path):
        raise UsageError("%s not found under %s" % (SURFACES_REL, root))
    try:
        return parse_surfaces(read_text(path))
    except UsageError as exc:
        raise UsageError("%s: %s" % (SURFACES_REL, exc))


# --------------------------------------------------------------------------
# LEDGER.md


class Entry(object):
    def __init__(self, entry_id, title, lineno):
        self.id = entry_id
        self.malformed = {}    # (pr, stem) -> message
        self.notes = []
        self.warnings = []     # printed with the notes; they never fail
        self.verdicts = {}     # (pr, stem) -> 'PASS', 'FAIL' or None
        self.enforcement = None


def lint(root):
    """Lint risk-paths.toml, enforcement.toml and every verdict file."""
    out = Lint()
    s = g.load_surfaces(root)
    reviewer_ids = s.reviewer_ids()
    rp, problems = g.load_risk_paths(root, reviewer_ids)
    out.rp = rp
    out.findings.extend(("review_check.config", p) for p in problems)
    if rp is not None and not problems and rp.signal_code == []:
        # Valid, but it silently disables the owner-signal tripwire (model S-005 AC4).
        out.warnings.append("WARNING: %s: signal_code = [] turns the owner-signal tripwire off — no changed "
                            "path can trip it; list the signal-code globs, or remove the key to use the "
                            "defaults" % g.RISK_PATHS_REL)
    out.enforcement = g.load_enforcement(root)
    out.findings.extend(("enforcement.lint", p) for p in out.enforcement.problems)
    files, out.notes = verdict_files(root)
    allowed = set(reviewer_ids) | {g.OWNER}
    v3 = g.is_v3(root)
    for pr, stem, rel in files:
        verdict = parse_verdict(g.read_text(os.path.join(root, rel), newline=""))
        out.verdicts[(pr, stem)] = verdict
        if verdict is None:
            out.malformed[(pr, stem)] = MALFORMED % rel
        if v3 and stem == PLAN_STEM and g.SPEC_REF_RE.match(pr):
            continue   # a v3 plan-review record, reviews/<spec id>/plan.md (model S-009 AC6)
        if stem not in allowed:
            out.findings.append(("review_check.lint", "%s: '%s' is neither 'owner' nor a reviewer-class roster id in %s"
                                 % (rel, stem, g.SURFACES_REL)))
    return out


def changed_files(root, base):
    if not g.git_ok(root, ["rev-parse", "--verify", "-q", "%s^{commit}" % base]):
        raise g.UsageError("base ref %r is not a commit in %s" % (base, root))

STAGES = (2, 3, 4, 5, 6, 8)
STATES = ("ready", "dispatched", "returned", "waiting-owner", "done", "closed")
ROLES = ("critic", "researcher", "source-checker", "definer", "definer-freeze", "check-author", "builder",
         "reviewer", "checks", "critic-triage")
VERDICTS = ("PASS", "FAIL", "malformed", "none")
GATES = ("dor", "dor-fail", "criteria", "launch", "evidence", "stop", "failure")
RESULTS = ("ok", "error", "timeout", "usage-limit")
CHECKERS = ("critic", "source-checker", "reviewer", "checks")   # verdict PASS or FAIL
BUDGET_EXEMPT = ("checks", "critic-triage")
FROZEN_STAGES = (4, 5, 6)
# AC5 confirm: the stage's checker (research: the Source checker).
CONFIRM_CHECKER = {2: "critic", 3: "critic", 4: "critic", 5: "checks", 6: "reviewer", 8: "critic"}
RESPECIFY_WORDS = ("re-specify", "criteria-wrong", "checks-wrong")
    st["gate"] = gate
    st["card"] = st.get("card", 0) + 1
    st.pop("dispatched_at", None)
    if resume:
        st["resume"] = resume
    else:
        st.pop("resume", None)
    action = {"kind": "card", "route": route_id, "gate": gate, "card": st["card"], "reason": reason,
              "resume": resume}
    action.update(extra)
    return action


def _dispatch(ctx, st, route_id, role, stage, run_checks):
    """A dispatch or check run, after the freeze pre-check and then the budget check (AC3)."""
    if stage != st["stage"]:
        st.update(stage=stage, sessions=0, attempts=0)
    exempt = role in BUDGET_EXEMPT
    if stage in FROZEN_STAGES and not ctx.is_frozen(st.get("spec")):
        return _card(st, "failure", route_id,
                     "A dispatch at stage %d needs a frozen spec, and %s is not frozen (D-043, D-046)."
                     % (stage, st.get("spec") or "the item's spec"))
    if not exempt and st["sessions"] >= ctx.routing.budget:
        return _card(st, "stop", route_id,
                     "The session budget for stage %d (%d) is used up." % (stage, ctx.routing.budget),
                     budget=True)
    # A re-dispatch after a usage-limit outcome does not count against the budget (AC8).
    if not exempt and "usage_limit_since" not in st:
        st["sessions"] += 1
    st.update(role=role, state="dispatched", last_verdict="none", dispatched_at=ctx.now_s)
    return {"kind": "dispatch", "route": route_id, "action": "run-checks" if run_checks else "dispatch",
            "role": role, "stage": stage, "spec": st.get("spec")}


def route_item(ctx, st):
    """Route one status (AC3). Returns (route id, new status, action or None)."""
    r = find_route(ctx.routing, st, ctx.is_frozen)
    rid, act = r["id"], r["action"]
    if act == "none":
        return rid, st, None
    st = dict(st)
    if act.startswith("card "):
        resume = r.get("resume")
        if resume == "this":
            resume = _this(st)
        return rid, st, _card(st, act[5:], rid, REASONS.get(rid, ""), resume)
    if act == "done":
        st["state"] = "done"
        return rid, st, {"kind": "done", "route": rid}
    if act == "run-checks":
        role = "checks"
    elif act == "dispatch item-role":
        role = st["role"]
    else:
        role = act[len("dispatch "):]
    return rid, st, _dispatch(ctx, st, rid, role, r.get("then_stage", st["stage"]), act == "run-checks")


def normalize_verdict(role, verdict):
    """AC8: PASS/FAIL for checkers and check runs, none for doers and Triage; else malformed."""
    if role in CHECKERS:
        return verdict if verdict in ("PASS", "FAIL") else "malformed"
    return "none" if verdict == "none" else "malformed"


def apply_outcome(ctx, st, result, verdict):
    """Apply a finished session or check run to a dispatched item (AC8). Returns (status, action)."""
    st = dict(st)
    st.pop("dispatched_at", None)
    action = None
    if result == "ok":
        v = normalize_verdict(st["role"], verdict)
        st.update(state="returned", last_verdict=v, attempts=0)
        st.pop("usage_limit_since", None)
        if v == "FAIL":
            st[round_key(st["stage"])] += 1
    elif result in ("error", "timeout"):
        st.pop("usage_limit_since", None)
        st.update(state="ready", last_verdict="none", attempts=min(st["attempts"] + 1, 2))
        if st["attempts"] >= 2:
            action = _card(st, "failure", "attempts",
                           "Two attempts in a row ended without a return (the last: %s)." % result, _this(st))
    elif result == "usage-limit":
        st.update(state="ready", last_verdict="none")
        since = st.setdefault("usage_limit_since", ctx.now_s)
        hours = ctx.routing.usage_limit_hours
        if ctx.now - parse_time(since) >= datetime.timedelta(hours=hours):
            action = _card(st, "failure", "usage-limit",
                           "The account has hit its usage limit on every try for %d hours (since %s)."
                           % (hours, since), _this(st))
    else:
        raise ValueError("unknown result %r" % (result,))
    return st, action


def word_list_key(st, gate):
class Step:
    def __init__(self, root, now, spec_dir, outcomes, routing_path):
        self.root = root
        self.now = now
        self.now_s = fmt_time(now)
        self.spec_dir = spec_dir
        self.outcomes_path = outcomes
        self.routing = load_routing(routing_path)
        self.items = {}          # valid items: id -> status
        self.original = {}       # id -> status file text as read
        self.all_ids = set()     # every status/*.toml name
        self.lines = []          # new dispatch-log lines (without time and prev)
        self.plan = []
        self.cards = []          # (rel, text)
        self.research = []       # (rel, text)
        self.trigger = {}
        self.records = {}
        self.touched = set()
        self.spec_cache = {}
        self.max_spec = 0
        self.ctx = Context(self.routing, now, self.is_frozen, self.new_spec)

    # -- paths and reading
    def path(self, rel):
        return os.path.join(self.root, *rel.split("/"))

    def listdir(self, rel):
        p = self.path(rel)
        return sorted(os.listdir(p)) if os.path.isdir(p) else []

    def read_text(self, path):
        with open(path, encoding="utf-8", newline="") as fh:
            return fh.read()

    # -- processed inputs and the log
    def load_processed(self):
        p = self.path(PROCESSED_REL)
        self.processed_text = None
        data = {}
        if os.path.exists(p):
            try:
                self.processed_text = self.read_text(p)
                data = json.loads(self.processed_text)
            except (OSError, ValueError) as exc:
                raise UsageError("%s is unreadable: %s" % (PROCESSED_REL, exc))
        self.processed = {"requests": list(data.get("requests", [])),
                          "outcomes": dict(data.get("outcomes", {})),
                          "decisions": dict(data.get("decisions", {})),
                          "anomalies": list(data.get("anomalies", [])),
                          "plan_hash": data.get("plan_hash"),
                          "log_head": data.get("log_head", GENESIS)}
        self.anomaly_keys = set(self.processed["anomalies"])

    def load_log(self):
        self.month = self.now.strftime("%Y-%m")
        months = [m.group(1) for m in (MONTH_FILE_RE.match(n) for n in self.listdir(LOG_DIR)) if m]
        if months and months[-1] > self.month:
            raise UsageError("--now (%s) is before the dispatch log's latest month (%s)" % (self.now_s, months[-1]))
        self.log_prev = GENESIS
        self.item_lines = {}
        for m in months:
            rel = "%s/%s.jsonl" % (LOG_DIR, m)
            for i, line in enumerate(self.read_text(self.path(rel)).split("\n"), 1):
                if not line:
                    continue
                self.log_prev = sha(line)
                try:
                    item = json.loads(line).get("item")
                except (ValueError, AttributeError):
                    item = None
                if item:
                    self.item_lines.setdefault(item, []).append((rel, i))

    def log(self, **fields):
        self.lines.append(fields)

    def anomaly(self, key, item, message):
        if key in self.anomaly_keys:
            return
        self.anomaly_keys.add(key)
        self.processed["anomalies"].append(key)
        self.log(trigger="anomaly", item=item, error=message)
        print("ERROR: %s%s" % ("%s: " % item if item else "", message), file=sys.stderr)

    # -- specs
    def spec_names(self):
        if not hasattr(self, "_spec_names"):
            self._spec_names = {}
            for n in sorted(os.listdir(self.spec_dir)):
                m = SPEC_NAME_RE.match(n)
                if m and n.endswith(".md") and not n.startswith("_"):
                    self._spec_names.setdefault(m.group(1), n)
        return self._spec_names

    def is_frozen(self, spec):
        if not spec:
            return False
        if spec not in self.spec_cache:
            name = self.spec_names().get(spec)
            status = None
            if name:
                with open(os.path.join(self.spec_dir, name), encoding="utf-8") as fh:
                    while True:
