def run(cmd, cwd, env=None):
    proc = subprocess.run(cmd, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
    return proc.returncode, proc.stdout.decode("utf-8", "replace")


def read(root, rel):
    with open(os.path.join(root, rel), encoding="utf-8", newline="") as fh:
        return fh.read()


def tree(root):
    out = set()
    for d, dirs, files in os.walk(root):
        dirs[:] = [x for x in dirs if x != ".git"]
        for f in files:
            out.add(os.path.relpath(os.path.join(d, f), root).replace(os.sep, "/"))
    return out


def front_matter(text):
    lines = text.split("\n")
    if not lines or lines[0] != "---":
        return None
    end = lines.index("---", 1)
    return dict(l.split(":", 1) for l in lines[1:end] if ":" in l)


def h2_sections(text):
    """[(heading, body)] of every `## ` section, outside fenced code."""
    out, fence, cur = [], False, None
    for line in text.split("\n"):
        if line.startswith("```"):
            fence = not fence
        if not fence and line.startswith("## "):
            cur = [line[3:].strip(), []]
            out.append(cur)
        elif cur is not None:
            cur[1].append(line)
    return [(h, "\n".join(b)) for h, b in out]


def numbered_sections(text):
    """{n: text} of each `## <n>. ` section (outside fenced code), from its heading line up to the
    next such heading or the end of the file."""
    out, fence, cur = {}, False, None
    for line in text.split("\n"):
        if line.startswith("```"):
            fence = not fence
        m = None if fence else re.match(r"^## (\d+)\. ", line)
        if m:
            cur = m.group(1)
            if cur in out:
                raise AssertionError("section %s appears twice" % cur)
            out[cur] = []
        if cur is not None:
            out[cur].append(line)
    return dict((n, "\n".join(ls)) for n, ls in out.items())


def witnesses(pattern):
    """Concrete paths a pack pattern matches: `**` and `*` filled in, placeholders kept as
    an item id no glob in the file could name."""
    p = pattern
    for ph in PLACEHOLDERS:
        p = p.replace(ph, "ITEM-" + ph.strip("{}"))
    out = []
    for fill in (("x/y", "x"), ("x", "x"), ("", "x")):
        w = p.replace("**", "\0").replace("*", fill[1]).replace("\0", fill[0])
        w = re.sub(r"/+", "/", w).strip("/")
        out.append(w)
    return out


def as_glob(pattern):
    p = pattern
    for ph in PLACEHOLDERS:
        p = p.replace(ph, "ITEM-" + ph.strip("{}"))
    return p


def overlaps(a, b):
    """True when some path could match both pack patterns (tested by witnesses both ways)."""
    return (any(govlib.glob_match(as_glob(a), w) for w in witnesses(b))
            or any(govlib.glob_match(as_glob(b), w) for w in witnesses(a)))


