# AC7 (the tool part): vendored comments cite the model's spec ids as "model S-nnn"


class ModelPrefixTests(unittest.TestCase):
    EXAMPLES = ("[S-001, S-002]", "[S-001]")   # format examples in messages, not citations

    def vendored_files(self):
        out = [os.path.join(_util.TOOLS, n) for n in sorted(os.listdir(_util.TOOLS))
               if n.endswith((".py", ".sh"))]
        for dirpath, _, names in os.walk(os.path.join(_util.REPO, "template/.github")):
            out.extend(os.path.join(dirpath, n) for n in sorted(names))
        return out

    def test_spec_ids_carry_the_model_prefix(self):
        bad = []
        for path in self.vendored_files():
            with open(path, encoding="utf-8") as fh:
                for i, line in enumerate(fh, 1):
                    for ex in self.EXAMPLES:
                        line = line.replace(ex, "")
                    for m in re.finditer(r"S-\d{3,}", line):
                        if not line[:m.start()].endswith("model "):
                            bad.append("%s:%d: %s" % (os.path.relpath(path, _util.REPO), i, line.strip()))
        self.assertEqual(bad, [])


